#!/usr/bin/env python3
from __future__ import annotations
import argparse, base64, json, shutil, subprocess, sys, zlib
from pathlib import Path

HERE=Path(__file__).resolve().parent
REPO=HERE.parents[1]
BASE=REPO/"integrations"/"fieldpilot-broker-exec-01"/"build_candidate.py"
PAYLOAD="""[... ELLIPSIZATION ...]"""
TRIAL_ZIP_SHA256="ed3a149ab4fa83da5b3322973e012ebae6a1ce8048f0e156a555c0b115c2599f"
BASE_COMMIT="55b1aa7824627b23304be869187dbc25d66e540d"
AGENT_REACH_PIN="a19a171fa980a0785849596492e0af4db800c82f"

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("--output",required=True)
    args=ap.parse_args()
    out=Path(args.output).resolve()
    if out.exists(): shutil.rmtree(out)
    subprocess.run([sys.executable,str(BASE),"--output",str(out)],check=True,cwd=REPO)
    files=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)).decode("utf-8"))
    for rel,content in files.items():
        dest=out/rel
        dest.parent.mkdir(parents=True,exist_ok=True)
        dest.write_text(content,encoding="utf-8")
    print(json.dumps({"status":"BUILT","output":str(out),"overlaid_files":len(files),"trial_zip_sha256":TRIAL_ZIP_SHA256,"base_commit":BASE_COMMIT,"agent_reach_pin":AGENT_REACH_PIN},ensure_ascii=False))

if __name__=="__main__": main()
